SELECT board_no, board_title, board_content, board_user, updatedate, createdate
FROM board
WHERE board_no = #{boardNo}

SELECT board_no, board_title, board_content, board_user, updatedate, createdate FROM board
board_title LIKE CONCAT('%', #{searchWord}, '%')
ORDER BY board_no DESC LIMIT #{beginRow}, #{rowPerPage}
